type Warehouse = { id: number; code: string; name: string; description?: string | null; active: boolean; primary: boolean; branchId?: number | null; branch?: { id: number; code: string; name: string } | null; balances: Array<{ productId?: number; quantity: number; reservedQuantity: number }> };
