type Detail = Branch & { productConfigurations: ProductConfiguration[]; userAccesses: UserAccess[]; financialAccounts: Array<{ id: number; code: string; name: string; type: string; currentBalance: number; active: boolean }>; financialTitles: Array<{ id: number; type: string; description: string; amount: number; paidAmount: number; dueAt: string; status: string }>; salesOrders: Array<{ id: number; number: string; customerName: string; total: number; status: string; placedAt: string }>; purchaseInvoices: Array<{ id: number; number: string; supplierName: string; total: number; status: string; issueDate: string }>; posRegisters: Array<{ id: number; code: string; name: string; status: string; warehouseId?: number | null; sessions: Array<{ id: number; number: string; status: string; openedAt: string }> }> };
type Data = { items: Branch[]; warehouses: Warehouse[]; products: Product[]; profiles: Profile[]; hierarchy: Array<{ id: number; code: string; name: string; type: string; status: string; state?: string | null; primary: boolean }>; activeBranchId: number | null; defaultTimezone: string; generatedAt: string; capabilities: { canWrite: boolean }; pagination: { page: number; limit: number; total: number; pages: number }; summary: { total: number; active: number; planned: number; inactive: number; headquarters: number; ready: number; critical: number; states: number; availableStock: number; userAccesses: number; blockers: number; unassignedWarehouses: number } };
type Filters = { search: string; status: string; type: string; state: string; readiness: string; sort: string };
