function Structure({ items, activeBranchId, canWrite, busy, openDetail, editBranch, selectBranch, setAction }: { items: Branch[]; activeBranchId: number | null; canWrite: boolean; busy: boolean; openDetail(id: number): Promise<void>; editBranch(id: number, mode?: "edit" | "duplicate"): Promise<void>; selectBranch(item: Branch): Promise<void>; setAction(value: { item: Branch; type: "status" | "primary" }): void }) {
  if (!items.length) return <Empty title="Nenhuma unidade encontrada" text="Ajuste os filtros ou cadastre a primeira empresa ou filial." />;
  return <section className={styles.cardGrid}>{items.map((item) => <article className={`${styles.branchCard} ${activeBranchId === item.id ? styles.selected : ""}`} key={item.id}><header><div className={styles.identity}><i>{initials(item.name)}</i><span><small>{item.type === "headquarters" ? "MATRIZ" : "FILIAL"} · {item.code}</small><button type="button" onClick={() => void openDetail(item.id)}>{item.name}</button><p>{item.city && item.state ? `${item.city} / ${item.state}` : "Localização não informada"}</p></span></div><div className={styles.headerBadges}>{item.primary && <em>Principal</em>}<Status value={item.status} /></div></header><div className={styles.legal}><strong>{item.legalName}</strong><span>{formatDocument(item.document)}</span>{item.parentBranch && <small>Vinculada a {item.parentBranch.name}</small>}</div><div className={styles.cardMetrics}><span><small>Prontidão</small><b className={styles[item.readiness.status]}>{item.readiness.score}%</b></span><span><small>Depósitos</small><b>{item.metrics.warehouseCount}</b></span><span><small>Equipe</small><b>{item.metrics.userCount}</b></span><span><small>Saldo</small><b>{number.format(item.metrics.availableStock)}</b></span></div><div className={styles.capabilities}>{capabilityLabels(item.settings).map((label) => <span key={label}>{label}</span>)}{!capabilityLabels(item.settings).length && <span className={styles.mutedChip}>Sem operação habilitada</span>}</div>{item.readiness.issues.length > 0 && <button type="button" className={styles.issueSummary} onClick={() => void openDetail(item.id)}><b>{item.readiness.issues.length}</b><span>{item.readiness.issues[0].label}{item.readiness.issues.length > 1 ? ` +${item.readiness.issues.length - 1}` : ""}</span></button>}<footer><button type="button" disabled={busy || item.status !== "active" || activeBranchId === item.id} onClick={() => void selectBranch(item)}>{activeBranchId === item.id ? "Em uso" : "Usar unidade"}</button><details className={styles.actions}><summary aria-label={`Ações de ${item.name}`}>•••</summary><div><button type="button" onClick={() => void openDetail(item.id)}>Ver visão 360</button>{canWrite && <><button type="button" onClick={() => void editBranch(item.id)}>Editar cadastro</button><button type="button" onClick={() => void editBranch(item.id, "duplicate")}>Duplicar configuração</button>{item.type === "headquarters" && item.status === "active" && !item.primary && <button type="button" onClick={() => setAction({ item, type: "primary" })}>Tornar matriz principal</button>}{!item.primary && <button type="button" className={item.status === "active" ? styles.dangerText : ""} onClick={() => setAction({ item, type: "status" })}>{item.status === "active" ? "Inativar unidade" : "Ativar unidade"}</button>}</>}</div></details></footer></article>)}</section>;
}

function ReadinessView({ items, openDetail, editBranch, canWrite }: { items: Branch[]; openDetail(id: number): Promise<void>; editBranch(id: number): Promise<void>; canWrite: boolean }) {
  if (!items.length) return <Empty title="Sem dados de prontidão" text="Nenhuma unidade atende aos filtros atuais." />;
  const checkKeys = ["legal", "tax", "address", "contact", "warehouse", "users", "catalog", "fiscal", "operation"];
  return <section className={styles.readinessPanel}><header><div><span>CHECKLIST OPERACIONAL</span><h2>Prontidão por unidade</h2></div><p>Itens críticos impedem ativação; alertas mantêm a operação visível para saneamento.</p></header><div className={styles.readinessScroll}><table><thead><tr><th>Unidade</th><th>Índice</th>{checkKeys.map((key) => <th key={key}>{shortCheck(key)}</th>)}<th>Ação</th></tr></thead><tbody>{items.map((item) => <tr key={item.id}><td><button type="button" onClick={() => void openDetail(item.id)}><strong>{item.name}</strong><small>{item.code} · {statusLabels[item.status]}</small></button></td><td><Score readiness={item.readiness} /></td>{checkKeys.map((key) => { const check = item.readiness.checks.find((value) => value.key === key); return <td key={key}><span className={check?.complete ? styles.checkOk : check?.critical ? styles.checkCritical : styles.checkWarn} title={check?.guidance}>{check?.complete ? "✓" : "!"}</span></td>; })}<td>{canWrite && <button type="button" className={styles.fixButton} onClick={() => void editBranch(item.id)}>Corrigir</button>}</td></tr>)}</tbody></table></div></section>;
}

function GovernanceView({ data, openDetail }: { data: Data; openDetail(id: number): Promise<void> }) {
  const headquarters = data.items.filter((item) => item.type === "headquarters"), orphanBranches = data.items.filter((item) => item.type === "branch" && !item.parentBranchId);
  return <section className={styles.governance}><article className={styles.panel}><header><div><span>HIERARQUIA</span><h2>Matrizes e unidades vinculadas</h2></div><b>{headquarters.length} grupo(s)</b></header><div className={styles.tree}>{headquarters.map((parent) => <section key={parent.id}><button type="button" onClick={() => void openDetail(parent.id)}><i>▣</i><span><strong>{parent.name}</strong><small>{parent.code} · {parent.primary ? "Matriz principal" : "Matriz"}</small></span><Status value={parent.status} /></button><div>{parent.childBranches.map((child) => <button type="button" key={child.id} onClick={() => void openDetail(child.id)}><i>└</i><span><strong>{child.name}</strong><small>{child.code}</small></span><Status value={child.status} /></button>)}{!parent.childBranches.length && <p>Nenhuma filial vinculada.</p>}</div></section>)}{!headquarters.length && <Empty title="Sem matriz" text="Cadastre uma matriz para organizar a estrutura jurídica." compact />}</div></article><article className={styles.panel}><header><div><span>EXCEÇÕES</span><h2>Fila de governança</h2></div><b>{data.summary.critical + data.summary.blockers + data.summary.unassignedWarehouses}</b></header><div className={styles.queue}><QueueItem count={data.summary.critical} title="Unidades críticas" text="Cadastro ou estrutura insuficiente para ativação segura." /><QueueItem count={data.summary.blockers} title="Operações abertas" text="Caixas, pedidos, reservas ou expedições impedem inativação." /><QueueItem count={data.summary.unassignedWarehouses} title="Depósitos sem filial" text="Estruturas de estoque aguardando vínculo operacional." /><QueueItem count={orphanBranches.length} title="Filiais sem matriz" text="Unidades juridicamente órfãs na hierarquia." /></div></article><article className={styles.guide}><span>MODELO DE CONTROLE</span><h2>Ciclo seguro de uma unidade</h2><ol><li><b>Planejar</b><p>Cadastre identidade, matriz responsável e início previsto.</p></li><li><b>Preparar</b><p>Configure fiscal, horários, depósitos, catálogo e acessos.</p></li><li><b>Ativar</b><p>Libere a operação somente após os itens críticos.</p></li><li><b>Monitorar</b><p>Acompanhe prontidão, certificados, DFe e dependências.</p></li><li><b>Inativar</b><p>Conclua operações e registre a justificativa auditável.</p></li></ol></article></section>;
}

function DetailModal({ branch, audit, loading, canWrite, close, edit, setAction }: { branch: Detail | null; audit: Audit[]; loading: boolean; canWrite: boolean; close(): void; edit(): void; setAction(value: { item: Branch; type: "status" | "primary" }): void }) {
  const [tab, setTab] = useState<"overview" | "operation" | "fiscal" | "finance" | "history">("overview");
  return <ErpModal className={styles.detailLayer} close={close} label="Visão 360 da unidade"><section className={styles.detailDialog}>{loading || !branch ? <div className={styles.detailLoading}>Carregando visão 360…</div> : <><header><div className={styles.detailIdentity}><i>{initials(branch.name)}</i><span><small>{branch.type === "headquarters" ? "MATRIZ" : "FILIAL"} · {branch.code}</small><h2>{branch.name}</h2><p>{branch.legalName} · {formatDocument(branch.document)}</p></span></div><Status value={branch.status} />{canWrite && <button type="button" onClick={edit}>Editar</button>}<button type="button" className={styles.close} onClick={close} aria-label="Fechar">×</button></header><nav className={styles.detailTabs} role="tablist">{[["overview", "Visão geral"], ["operation", "Operação"], ["fiscal", "Fiscal e DFe"], ["finance", "Financeiro"], ["history", "Histórico"]].map(([id, label]) => <button type="button" role="tab" aria-selected={tab === id} key={id} onClick={() => setTab(id as typeof tab)}>{label}</button>)}</nav><div className={styles.detailBody}>
      {tab === "overview" && <div className={styles.detailGrid}><section className={styles.detailMetrics}><MetricValue label="Prontidão" value={`${branch.readiness.score}%`} /><MetricValue label="Saldo disponível" value={number.format(branch.metrics.availableStock)} /><MetricValue label="Equipe" value={String(branch.metrics.userCount)} /><MetricValue label="Pendências operacionais" value={String(branch.blockers.total)} /></section><Info title="Identidade e localização"><dl><InfoRow label="Razão social" value={branch.legalName} /><InfoRow label="CNPJ" value={formatDocument(branch.document)} /><InfoRow label="CNAE" value={formatActivity(branch.activityCode)} /><InfoRow label="Inscrição estadual" value={branch.stateRegistrationExempt ? "Isenta" : branch.stateRegistration} /><InfoRow label="Centro de custo" value={branch.costCenterCode} /><InfoRow label="Abertura" value={formatDate(branch.openingDate)} /><InfoRow label="Matriz vinculada" value={branch.parentBranch?.name} /><InfoRow label="Endereço" value={address(branch)} /></dl></Info><Info title="Contato responsável"><dl><InfoRow label="Unidade" value={branch.email || branch.phone} /><InfoRow label="Responsável" value={branch.managerName} /><InfoRow label="Contato" value={branch.managerEmail || branch.managerPhone} /><InfoRow label="Fuso horário" value={branch.timezone} /></dl>{branch.notes && <p>{branch.notes}</p>}</Info><section className={`${styles.info} ${styles.wide}`}><header><h3>Checklist de prontidão</h3><Score readiness={branch.readiness} /></header><div className={styles.checkGrid}>{branch.readiness.checks.map((check) => <article key={check.key} className={check.complete ? styles.complete : check.critical ? styles.incomplete : styles.warning}><i>{check.complete ? "✓" : "!"}</i><span><strong>{check.label}</strong><small>{check.complete ? "Concluído" : check.guidance}</small></span></article>)}</div></section></div>}
      {tab === "operation" && <div className={styles.detailGrid}><Info title="Capacidades"><div className={styles.capabilityList}>{operationCapabilities(branch.settings).map((item) => <span className={item.enabled ? styles.enabled : styles.disabled} key={item.label}><i>{item.enabled ? "✓" : "—"}</i>{item.label}</span>)}</div></Info><Info title="Horários"><div className={styles.schedule}>{normalizeBusinessHours(branch.settings?.businessHours).map((item) => <span key={item.day}><b>{dayLabel(item.day)}</b><small>{item.enabled ? `${item.opensAt}–${item.closesAt}` : "Fechado"}</small></span>)}</div></Info><Info title={`Depósitos (${branch.warehouses.length})`} wide><div className={styles.entityList}>{branch.warehouses.map((item) => <article key={item.id}><span><strong>{item.name}</strong><small>{item.code}{branch.defaultWarehouseId === item.id ? " · padrão" : ""}</small></span><b>{number.format(item.balances.reduce((sum, value) => sum + value.quantity - value.reservedQuantity, 0))} disponível</b></article>)}</div></Info><Info title={`Caixas e dependências (${branch.blockers.total})`} wide><div className={styles.dependencyGrid}><Dependency count={branch.blockers.openCashSessions} label="Caixas abertos" /><Dependency count={branch.blockers.openOrders} label="Pedidos em curso" /><Dependency count={branch.blockers.activeReservations} label="Reservas ativas" /><Dependency count={branch.blockers.activePickingWaves} label="Ondas abertas" /><Dependency count={branch.blockers.openManifests} label="Manifestos abertos" /></div>{branch.blockers.total > 0 && <p>Estas operações precisam ser concluídas antes da inativação.</p>}</Info></div>}
      {tab === "fiscal" && <div className={styles.detailGrid}><Info title="Configuração fiscal"><dl><InfoRow label="Regime" value={taxLabel(branch.settings?.taxRegime)} /><InfoRow label="Ambiente" value={statusLabels[branch.settings?.fiscalEnvironment || ""]} /><InfoRow label="Série NF-e" value={String(branch.settings?.nfeSeries || "—")} /><InfoRow label="Próxima NF-e" value={String(branch.settings?.nextNfeNumber || "—")} /><InfoRow label="Série NFC-e" value={String(branch.settings?.nfceSeries || "—")} /><InfoRow label="Série NFS-e" value={String(branch.settings?.nfseSeries || "—")} /></dl></Info><Info title={`Certificados A1 (${branch.fiscalCertificates.length})`}><div className={styles.entityList}>{branch.fiscalCertificates.map((item) => <article key={item.id}><span><strong>{item.name}</strong><small>Vence {formatDate(item.expiresAt)}</small></span><Status value={new Date(item.expiresAt) >= new Date() && item.active ? "active" : "inactive"} /></article>)}{!branch.fiscalCertificates.length && <p>Nenhum certificado vinculado.</p>}</div></Info><Info title="Distribuição de DFe" wide><div className={styles.entityList}>{branch.dfeSyncCursors.map((item, index) => <article key={item.id || index}><span><strong>{item.source || "SEFAZ NF-e"} · {statusLabels[item.environment || ""] || item.environment}</strong><small>{item.lastSuccessAt ? `Último sucesso ${dateTime.format(new Date(item.lastSuccessAt))}` : "Sem sincronização concluída"}</small></span><Status value={item.enabled && !item.consecutiveFailures ? "active" : item.consecutiveFailures ? "attention" : "inactive"} /></article>)}{!branch.dfeSyncCursors.length && <p>Distribuição de documentos ainda não configurada.</p>}</div></Info></div>}
      {tab === "finance" && <div className={styles.detailGrid}><Info title={`Contas financeiras (${branch.financialAccounts.length})`}><div className={styles.entityList}>{branch.financialAccounts.map((item) => <article key={item.id}><span><strong>{item.name}</strong><small>{item.code} · {item.type}</small></span><b>{money.format(item.currentBalance)}</b></article>)}{!branch.financialAccounts.length && <p>Nenhuma conta exclusiva da unidade.</p>}</div></Info><Info title={`Títulos recentes (${branch.financialTitles.length})`}><div className={styles.entityList}>{branch.financialTitles.slice(0, 6).map((item) => <article key={item.id}><span><strong>{item.description}</strong><small>Vence {formatDate(item.dueAt)}</small></span><b>{money.format(item.amount - item.paidAmount)}</b></article>)}{!branch.financialTitles.length && <p>Nenhum título vinculado.</p>}</div></Info><Info title="Pedidos e entradas recentes" wide><div className={styles.splitLists}><div>{branch.salesOrders.map((item) => <article key={item.id}><span><strong>{item.number} · {item.customerName}</strong><small>{formatDate(item.placedAt)} · {statusLabels[item.status] || item.status}</small></span><b>{money.format(item.total)}</b></article>)}</div><div>{branch.purchaseInvoices.map((item) => <article key={item.id}><span><strong>NF {item.number} · {item.supplierName}</strong><small>{formatDate(item.issueDate)} · {statusLabels[item.status] || item.status}</small></span><b>{money.format(item.total)}</b></article>)}</div></div></Info></div>}
      {tab === "history" && <div className={styles.detailGrid}><Info title={`Equipe autorizada (${branch.userAccesses.length})`}><div className={styles.entityList}>{branch.userAccesses.map((item) => <article key={item.userProfileId}><span><strong>{item.userProfile?.displayName || "Usuário"}</strong><small>{[item.canSell && "Vendas", item.canManageStock && "Estoque", item.canIssueFiscal && "Fiscal", item.primary && "Filial principal"].filter(Boolean).join(" · ")}</small></span></article>)}</div></Info><Info title={`Histórico auditável (${audit.length})`}><div className={styles.timeline}>{audit.map((item) => <article key={item.id}><i /><span><strong>{actionLabels[item.action] || item.action}</strong><small>{dateTime.format(new Date(item.createdAt))} · {item.actorId || "Sistema"}</small></span></article>)}{!audit.length && <p>Nenhum evento registrado.</p>}</div></Info>{canWrite && <section className={`${styles.info} ${styles.wide}`}><header><h3>Ações governadas</h3></header><div className={styles.governedActions}>{branch.type === "headquarters" && branch.status === "active" && !branch.primary && <button type="button" onClick={() => setAction({ item: branch, type: "primary" })}>Tornar matriz principal</button>}{!branch.primary && <button type="button" className={branch.status === "active" ? styles.dangerButton : styles.primary} onClick={() => setAction({ item: branch, type: "status" })}>{branch.status === "active" ? "Inativar unidade" : "Ativar unidade"}</button>}</div></section>}</div>}
    </div></>}</section></ErpModal>;
}

function BranchEditor({ state, data, busy, close, submit }: { state: EditorState; data: Data; busy: boolean; close(): void; submit(payload: Record<string, unknown>): Promise<void> }) {
  const source = state.item, duplicate = state.mode === "duplicate", [tab, setTab] = useState("identity"), [selectedWarehouses, setSelectedWarehouses] = useState<number[]>(duplicate ? [] : source?.warehouses.map((item) => item.id) || []), [products, setProducts] = useState<ProductConfiguration[]>(() => source?.productConfigurations.length ? source.productConfigurations.map((item) => ({ ...item, preferredWarehouseId: duplicate ? null : item.preferredWarehouseId })) : data.products.map((item) => defaultProduct(item))), [accesses, setAccesses] = useState<UserAccess[]>(() => duplicate ? [] : source?.userAccesses.map(({ userProfile: _profile, ...item }) => { void _profile; return item; }) || []), [hours, setHours] = useState<BusinessHour[]>(() => normalizeBusinessHours(source?.settings?.businessHours)), [productQuery, setProductQuery] = useState(""), [type, setType] = useState(source?.type || "branch");
  const availableWarehouses = data.warehouses.filter((item) => !item.branchId || (!duplicate && item.branchId === source?.id)), selectedProducts = products.filter((item) => item.active).length, selectedProfiles = accesses.length;
  function toggleWarehouse(id: number) { setSelectedWarehouses((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]); if (selectedWarehouses.includes(id)) setProducts((current) => current.map((item) => item.preferredWarehouseId === id ? { ...item, preferredWarehouseId: null } : item)); }
  function updateProduct(id: number, values: Partial<ProductConfiguration>) { setProducts((current) => current.map((item) => item.productId === id ? { ...item, ...values } : item)); }
  function toggleAccess(id: number) { setAccesses((current) => current.some((item) => item.userProfileId === id) ? current.filter((item) => item.userProfileId !== id) : [...current, { userProfileId: id, canSell: true, canManageStock: false, canIssueFiscal: false, primary: false }]); }
  function updateAccess(id: number, values: Partial<UserAccess>) { setAccesses((current) => current.map((item) => item.userProfileId === id ? { ...item, ...values } : item)); }
  async function save(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = event.currentTarget, values = Object.fromEntries(new FormData(form)); await submit({ ...values, type, status: state.mode === "edit" ? source?.status : values.status, expectedVersion: state.mode === "edit" ? source?.version : undefined, warehouseIds: selectedWarehouses, defaultWarehouseId: values.defaultWarehouseId ? Number(values.defaultWarehouseId) : null, productConfigurations: products, userAccesses: accesses, businessHours: hours, stateRegistrationExempt: new FormData(form).has("stateRegistrationExempt"), reserveStockOnOrder: new FormData(form).has("reserveStockOnOrder"), allowCrossBranchFulfillment: new FormData(form).has("allowCrossBranchFulfillment"), autoTransferEnabled: new FormData(form).has("autoTransferEnabled"), salesEnabled: new FormData(form).has("salesEnabled"), purchasesEnabled: new FormData(form).has("purchasesEnabled"), stockEnabled: new FormData(form).has("stockEnabled"), fiscalEnabled: new FormData(form).has("fiscalEnabled"), servicesEnabled: new FormData(form).has("servicesEnabled") }); }
  const tabs = [["identity", "Identificação"], ["address", "Endereço"], ["operation", "Operação"], ["fiscal", "Fiscal"], ["warehouses", `Depósitos (${selectedWarehouses.length})`], ["catalog", `Catálogo (${selectedProducts})`], ["users", `Equipe (${selectedProfiles})`]];
  return <ErpModal className={styles.editorLayer} close={close} label={state.mode === "edit" ? "Editar unidade" : "Cadastrar unidade"}><form className={styles.editorDialog} onSubmit={save}><header><div><span>ESTRUTURA EMPRESARIAL</span><h2>{state.mode === "edit" ? `Editar ${source?.name}` : duplicate ? "Duplicar configuração" : "Nova empresa ou filial"}</h2><p>{duplicate ? "A configuração foi copiada; informe os identificadores exclusivos e novos vínculos." : "Complete os dados por etapa. Unidades incompletas podem ser salvas como planejadas."}</p></div><button type="button" onClick={close} aria-label="Fechar">×</button></header><nav className={styles.editorTabs} aria-label="Etapas do cadastro">{tabs.map(([id, label]) => <button type="button" key={id} aria-current={tab === id ? "step" : undefined} onClick={() => setTab(id)}>{label}</button>)}</nav><div className={styles.editorBody}>
    <fieldset hidden={tab !== "identity"}><legend>Identidade jurídica e hierarquia</legend><label>Código operacional<input name="code" defaultValue={duplicate ? "" : source?.code || ""} placeholder="Ex.: FILIAL-SUL" required maxLength={30} /></label><label>Tipo<select name="type" value={type} onChange={(event) => setType(event.target.value)}><option value="headquarters">Matriz</option><option value="branch">Filial</option></select></label><label className={styles.wide}>Nome da unidade<input name="name" defaultValue={duplicate ? `${source?.name || "Unidade"} - nova` : source?.name || ""} required maxLength={120} /></label><label className={styles.wide}>Razão social<input name="legalName" defaultValue={source?.legalName || ""} required maxLength={180} /></label><label>CNPJ<input name="document" defaultValue={duplicate ? "" : formatDocument(source?.document)} inputMode="numeric" placeholder="00.000.000/0000-00" required /></label><label>CNAE principal<input name="activityCode" defaultValue={formatActivity(source?.activityCode)} inputMode="numeric" placeholder="0000-0/00" /></label>{type === "branch" && <label className={styles.wide}>Matriz vinculada<select name="parentBranchId" defaultValue={source?.parentBranchId || ""}><option value="">Sem vínculo</option>{data.hierarchy.filter((item) => item.type === "headquarters" && item.status !== "inactive" && item.id !== source?.id).map((item) => <option value={item.id} key={item.id}>{item.name} · {item.code}</option>)}</select></label>}<label>Situação inicial<select name="status" defaultValue={state.mode === "edit" ? source?.status : "planned"} disabled={state.mode === "edit"}><option value="planned">Planejada</option><option value="active">Ativa</option><option value="inactive">Inativa</option></select><small>{state.mode === "edit" ? "Use a ação governada para alterar a situação." : "Ativação exige itens críticos completos."}</small></label><label>Início da operação<input name="openingDate" type="date" defaultValue={dateInput(source?.openingDate)} /></label><label>Centro de custo<input name="costCenterCode" defaultValue={source?.costCenterCode || ""} maxLength={40} /></label><label>Fuso horário operacional<select name="timezone" defaultValue={source?.timezone || data.defaultTimezone}>{BRAZIL_TIME_ZONES.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select><small>Controla datas comerciais, caixa, estoque, fiscal e relatórios desta unidade.</small></label><label>Inscrição estadual<input name="stateRegistration" defaultValue={source?.stateRegistration || ""} maxLength={30} /></label><label className={styles.inlineCheck}><input type="checkbox" name="stateRegistrationExempt" defaultChecked={source?.stateRegistrationExempt} />Contribuinte isento de IE</label><label>Inscrição municipal<input name="municipalRegistration" defaultValue={source?.municipalRegistration || ""} maxLength={30} /></label><label className={styles.wide}>Observações internas<textarea name="notes" defaultValue={source?.notes || ""} maxLength={2000} rows={4} /></label></fieldset>
    <fieldset hidden={tab !== "address"}><legend>Endereço e contatos</legend><label>CEP<input name="zip" defaultValue={source?.zip || ""} inputMode="numeric" maxLength={10} /></label><label>UF<input name="state" defaultValue={source?.state || ""} maxLength={2} /></label><label className={styles.wide}>Logradouro<input name="street" defaultValue={source?.street || ""} maxLength={180} /></label><label>Número<input name="number" defaultValue={source?.number || ""} maxLength={30} /></label><label>Complemento<input name="complement" defaultValue={source?.complement || ""} maxLength={120} /></label><label>Bairro<input name="district" defaultValue={source?.district || ""} maxLength={120} /></label><label>Cidade<input name="city" defaultValue={source?.city || ""} maxLength={120} /></label><div className={styles.sectionTitle}><strong>Contato da unidade</strong><small>Usado em documentos e comunicações operacionais.</small></div><label>E-mail<input name="email" type="email" defaultValue={source?.email || ""} maxLength={254} /></label><label>Telefone<input name="phone" defaultValue={source?.phone || ""} maxLength={24} /></label><div className={styles.sectionTitle}><strong>Responsável local</strong><small>Pessoa acionada em alertas, aprovações e incidentes.</small></div><label>Nome<input name="managerName" defaultValue={source?.managerName || ""} maxLength={160} /></label><label>E-mail<input name="managerEmail" type="email" defaultValue={source?.managerEmail || ""} maxLength={254} /></label><label>Telefone<input name="managerPhone" defaultValue={source?.managerPhone || ""} maxLength={24} /></label></fieldset>
    <fieldset hidden={tab !== "operation"}><legend>Capacidades e horários</legend><div className={`${styles.toggleGrid} ${styles.wide}`}>{[["salesEnabled", "Vendas", "Pedidos, PDV e faturamento", source?.settings?.salesEnabled ?? true], ["purchasesEnabled", "Compras", "Cotações, pedidos e recebimento", source?.settings?.purchasesEnabled ?? true], ["stockEnabled", "Estoque", "Saldos, inventário e transferências", source?.settings?.stockEnabled ?? true], ["fiscalEnabled", "Fiscal", "NF-e, NFC-e, NFS-e e DFe", source?.settings?.fiscalEnabled ?? true], ["servicesEnabled", "Serviços", "Ordens de serviço e agenda", source?.settings?.servicesEnabled ?? true]].map(([name, title, text, checked]) => <label key={String(name)}><input type="checkbox" name={String(name)} defaultChecked={Boolean(checked)} /><span><strong>{String(title)}</strong><small>{String(text)}</small></span></label>)}</div><div className={styles.sectionTitle}><strong>Horário semanal</strong><small>Dias fechados não entram na disponibilidade operacional.</small></div><div className={`${styles.hoursGrid} ${styles.wide}`}>{hours.map((item) => <article key={item.day}><label className={styles.dayToggle}><input type="checkbox" checked={item.enabled} onChange={(event) => setHours((current) => current.map((value) => value.day === item.day ? { ...value, enabled: event.target.checked } : value))} />{dayLabel(item.day)}</label><input type="time" aria-label={`Abertura ${dayLabel(item.day)}`} disabled={!item.enabled} value={item.opensAt} onChange={(event) => setHours((current) => current.map((value) => value.day === item.day ? { ...value, opensAt: event.target.value } : value))} /><span>até</span><input type="time" aria-label={`Fechamento ${dayLabel(item.day)}`} disabled={!item.enabled} value={item.closesAt} onChange={(event) => setHours((current) => current.map((value) => value.day === item.day ? { ...value, closesAt: event.target.value } : value))} /></article>)}</div></fieldset>
    <fieldset hidden={tab !== "fiscal"}><legend>Política fiscal e numeração</legend><label>Regime tributário<select name="taxRegime" defaultValue={source?.settings?.taxRegime || "simples_nacional"}><option value="simples_nacional">Simples Nacional</option><option value="lucro_presumido">Lucro Presumido</option><option value="lucro_real">Lucro Real</option><option value="mei">MEI</option></select></label><label>Ambiente<select name="fiscalEnvironment" defaultValue={source?.settings?.fiscalEnvironment || "homologation"}><option value="homologation">Homologação</option><option value="production">Produção</option></select></label><label>Série NF-e<input name="nfeSeries" type="number" min="1" max="999" defaultValue={source?.settings?.nfeSeries || 1} required /></label><label>Série NFC-e<input name="nfceSeries" type="number" min="1" max="999" defaultValue={source?.settings?.nfceSeries || 1} required /></label><label>Série NFS-e<input name="nfseSeries" type="number" min="1" max="999" defaultValue={source?.settings?.nfseSeries || 1} required /></label><div className={`${styles.callout} ${styles.wide}`}><strong>Numeração protegida</strong><p>Os próximos números fiscais são mantidos pelo sistema e não são sobrescritos neste cadastro. Em produção, um certificado A1 válido será sinalizado na prontidão.</p></div></fieldset>
    <fieldset hidden={tab !== "warehouses"}><legend>Depósitos e abastecimento</legend><div className={`${styles.picker} ${styles.wide}`}>{availableWarehouses.map((item) => <label key={item.id}><input type="checkbox" checked={selectedWarehouses.includes(item.id)} onChange={() => toggleWarehouse(item.id)} /><span><strong>{item.name}</strong><small>{item.code} · {number.format(item.balances.reduce((sum, value) => sum + value.quantity - value.reservedQuantity, 0))} disponível</small></span></label>)}{!availableWarehouses.length && <p>Nenhum depósito livre para vínculo.</p>}</div><label className={styles.wide}>Depósito padrão<select name="defaultWarehouseId" defaultValue={duplicate ? "" : source?.defaultWarehouseId || ""}><option value="">Selecione</option>{availableWarehouses.filter((item) => selectedWarehouses.includes(item.id)).map((item) => <option value={item.id} key={item.id}>{item.name} · {item.code}</option>)}</select></label><label>Alocação<select name="stockAllocationStrategy" defaultValue={source?.settings?.stockAllocationStrategy || "local_first"}><option value="local_first">Priorizar estoque local</option><option value="highest_stock">Maior saldo disponível</option><option value="lowest_cost">Menor custo logístico</option></select></label><div className={`${styles.toggleGrid} ${styles.wide}`}><Check name="reserveStockOnOrder" title="Reservar no pedido" text="Protege o saldo contra venda simultânea." checked={source?.settings?.reserveStockOnOrder ?? true} /><Check name="allowCrossBranchFulfillment" title="Atendimento entre filiais" text="Consulta saldo de outras unidades." checked={source?.settings?.allowCrossBranchFulfillment ?? false} /><Check name="autoTransferEnabled" title="Sugerir transferência" text="Apoia a reposição entre depósitos." checked={source?.settings?.autoTransferEnabled ?? false} /></div></fieldset>
    <fieldset hidden={tab !== "catalog"} className={styles.catalogFieldset}><legend>Catálogo local</legend><div className={`${styles.catalogToolbar} ${styles.wide}`}><label>Buscar item<input value={productQuery} onChange={(event) => setProductQuery(event.target.value)} placeholder="Nome ou SKU" /></label><div><button type="button" onClick={() => setProducts((current) => current.map((item) => ({ ...item, active: true })))}>Ativar todos</button><button type="button" onClick={() => setProducts((current) => current.map((item) => ({ ...item, active: false })))}>Desativar todos</button></div></div><div className={`${styles.productList} ${styles.wide}`}>{data.products.filter((item) => `${item.name} ${item.sku}`.toLowerCase().includes(productQuery.toLowerCase())).map((item) => { const config = products.find((value) => value.productId === item.id) || defaultProduct(item); return <article className={config.active ? "" : styles.dimmed} key={item.id}><header><label><input type="checkbox" checked={config.active} onChange={(event) => updateProduct(item.id, { active: event.target.checked })} /><span><strong>{item.name}</strong><small>{item.sku} · {item.type === "service" ? "Serviço" : item.unit}</small></span></label><b>{money.format(config.priceOverride ?? item.price)}</b></header><div><NumberField label="Preço" value={config.priceOverride} change={(value) => updateProduct(item.id, { priceOverride: value })} /><NumberField label="Custo" value={config.costOverride} change={(value) => updateProduct(item.id, { costOverride: value })} /><NumberField label="Mínimo" value={config.minStock} disabled={item.type === "service"} change={(value) => updateProduct(item.id, { minStock: value })} /><NumberField label="Máximo" value={config.maxStock} disabled={item.type === "service"} change={(value) => updateProduct(item.id, { maxStock: value })} /><NumberField label="Reposição em" value={config.reorderPoint} disabled={item.type === "service"} change={(value) => updateProduct(item.id, { reorderPoint: value })} /><NumberField label="Qtd. reposição" value={config.reorderQuantity} disabled={item.type === "service"} change={(value) => updateProduct(item.id, { reorderQuantity: value })} /><label>Depósito preferencial<select disabled={item.type === "service"} value={config.preferredWarehouseId || ""} onChange={(event) => updateProduct(item.id, { preferredWarehouseId: event.target.value ? Number(event.target.value) : null })}><option value="">Padrão</option>{availableWarehouses.filter((warehouse) => selectedWarehouses.includes(warehouse.id)).map((warehouse) => <option value={warehouse.id} key={warehouse.id}>{warehouse.name}</option>)}</select></label><label>Localização<input disabled={item.type === "service"} value={config.location || ""} onChange={(event) => updateProduct(item.id, { location: event.target.value })} /></label><label>Lead time (dias)<input type="number" min="0" max="365" value={config.leadTimeDays} onChange={(event) => updateProduct(item.id, { leadTimeDays: Number(event.target.value) })} /></label><label className={styles.inlineCheck}><input type="checkbox" checked={config.saleEnabled} onChange={(event) => updateProduct(item.id, { saleEnabled: event.target.checked })} />Venda</label><label className={styles.inlineCheck}><input type="checkbox" checked={config.purchaseEnabled} onChange={(event) => updateProduct(item.id, { purchaseEnabled: event.target.checked })} />Compra</label></div></article>; })}</div></fieldset>
    <fieldset hidden={tab !== "users"}><legend>Equipe e escopo local</legend><div className={`${styles.accessList} ${styles.wide}`}>{data.profiles.map((profile) => { const access = accesses.find((item) => item.userProfileId === profile.id); return <article key={profile.id}><label><input type="checkbox" checked={Boolean(access)} onChange={() => toggleAccess(profile.id)} /><span><strong>{profile.displayName}</strong><small>{profile.jobTitle || profile.department || profile.email}</small></span></label>{access && <div><label><input type="checkbox" checked={access.canSell} onChange={(event) => updateAccess(profile.id, { canSell: event.target.checked })} />Vendas</label><label><input type="checkbox" checked={access.canManageStock} onChange={(event) => updateAccess(profile.id, { canManageStock: event.target.checked })} />Estoque</label><label><input type="checkbox" checked={access.canIssueFiscal} onChange={(event) => updateAccess(profile.id, { canIssueFiscal: event.target.checked })} />Fiscal</label><label><input type="checkbox" checked={access.primary} onChange={(event) => updateAccess(profile.id, { primary: event.target.checked })} />Unidade principal</label></div>}</article>; })}{!data.profiles.length && <p>Nenhum usuário ativo disponível.</p>}</div></fieldset>
  </div><footer><span>{state.mode === "edit" ? `Versão ${source?.version} · alterações concorrentes serão bloqueadas` : "Cadastros planejados podem ser completados antes da ativação"}</span><div><button type="button" onClick={close}>Cancelar</button><button type="submit" className={styles.primary} disabled={busy}>{busy ? "Salvando…" : state.mode === "edit" ? "Salvar alterações" : "Cadastrar unidade"}</button></div></footer></form></ErpModal>;
}

function ActionModal({ action, busy, close, submit }: { action: { item: Branch; type: "status" | "primary" }; busy: boolean; close(): void; submit(reason: string): Promise<void> }) { const isInactivate = action.type === "status" && action.item.status === "active"; return <ErpModal className={styles.actionLayer} close={close} label="Confirmar ação governada"><form className={styles.actionDialog} onSubmit={(event) => { event.preventDefault(); const values = new FormData(event.currentTarget); void submit(String(values.get("reason") || "")); }}><header><span>{action.type === "primary" ? "MATRIZ PRINCIPAL" : isInactivate ? "INATIVAÇÃO CONTROLADA" : "ATIVAÇÃO CONTROLADA"}</span><h2>{action.item.name}</h2><p>{action.type === "primary" ? "A unidade passará a representar a matriz principal do tenant." : isInactivate ? "A operação será bloqueada para novos processos. Dependências abertas impedem a conclusão." : "A unidade será liberada após validação automática dos itens críticos."}</p></header>{isInactivate && action.item.blockers.total > 0 && <div className={styles.blockerAlert}><strong>{action.item.blockers.total} dependência(s) detectada(s)</strong><span>Conclua caixas, pedidos, reservas, ondas e manifestos antes de tentar inativar.</span></div>}<label>Motivo da alteração<textarea name="reason" required minLength={4} maxLength={500} placeholder="Registre o contexto para a auditoria…" rows={4} /></label><footer><button type="button" onClick={close}>Cancelar</button><button type="submit" className={isInactivate ? styles.dangerButton : styles.primary} disabled={busy}>{busy ? "Processando…" : "Confirmar alteração"}</button></footer></form></ErpModal>; }
function Metric({ icon, label, value, detail, tone }: { icon: string; label: string; value: string; detail: string; tone?: "warn" | "good" }) { return <article className={tone ? styles[tone] : ""}><i>{icon}</i><span><small>{label}</small><strong>{value}</strong><b>{detail}</b></span></article>; }
function MetricValue({ label, value }: { label: string; value: string }) { return <div><small>{label}</small><strong>{value}</strong></div>; }
function Status({ value }: { value: string }) { return <em className={`${styles.badge} ${styles[value] || ""}`}>{statusLabels[value] || value}</em>; }
function Score({ readiness }: { readiness: Readiness }) { return <span className={`${styles.score} ${styles[readiness.status]}`}><i style={{ "--score": `${readiness.score * 3.6}deg` } as React.CSSProperties} /><b>{readiness.score}%</b></span>; }
function Info({ title, children, wide = false }: { title: string; children: React.ReactNode; wide?: boolean }) { return <section className={`${styles.info} ${wide ? styles.wide : ""}`}><header><h3>{title}</h3></header>{children}</section>; }
function InfoRow({ label, value }: { label: string; value?: string | null }) { return <div><dt>{label}</dt><dd>{value || "Não informado"}</dd></div>; }
function Dependency({ count, label }: { count: number; label: string }) { return <span className={count ? styles.hasDependency : ""}><b>{count}</b><small>{label}</small></span>; }
function QueueItem({ count, title, text }: { count: number; title: string; text: string }) { return <article className={count ? styles.queueAlert : ""}><b>{count}</b><span><strong>{title}</strong><small>{text}</small></span></article>; }
function Check({ name, title, text, checked }: { name: string; title: string; text: string; checked: boolean }) { return <label><input type="checkbox" name={name} defaultChecked={checked} /><span><strong>{title}</strong><small>{text}</small></span></label>; }
function NumberField({ label, value, disabled, change }: { label: string; value?: number | null; disabled?: boolean; change(value: number | null): void }) { return <label>{label}<input type="number" min="0" step="0.001" disabled={disabled} value={value ?? ""} onChange={(event) => change(event.target.value === "" ? null : Number(event.target.value))} /></label>; }
function Empty({ title, text, compact = false }: { title: string; text: string; compact?: boolean }) { return <section className={`${styles.empty} ${compact ? styles.compact : ""}`}><b>◇</b><strong>{title}</strong><p>{text}</p></section>; }
function Loading() { return <div className={styles.loading}><div /><div /><div /><section /></div>; }
function Fatal({ message, retry }: { message: string; retry(): void }) { return <section className={styles.fatal}><ErpIcon name="branches" /><h2>Não foi possível abrir empresas e filiais</h2><p>{message}</p><button type="button" onClick={retry}>Tentar novamente</button></section>; }
function defaultProduct(item: Product): ProductConfiguration { return { productId: item.id, active: item.active, saleEnabled: true, purchaseEnabled: item.type === "product", priceOverride: null, costOverride: null, minStock: item.type === "product" ? item.minStock : null, maxStock: null, reorderPoint: item.type === "product" ? item.minStock : null, reorderQuantity: item.type === "product" ? Math.max(item.minStock, 1) : null, preferredWarehouseId: null, location: null, leadTimeDays: 0 }; }
function capabilityLabels(settings?: Settings | null) { return operationCapabilities(settings).filter((item) => item.enabled).map((item) => item.label); }
function operationCapabilities(settings?: Settings | null) { return [{ label: "Vendas", enabled: settings?.salesEnabled ?? true }, { label: "Compras", enabled: settings?.purchasesEnabled ?? true }, { label: "Estoque", enabled: settings?.stockEnabled ?? true }, { label: "Fiscal", enabled: settings?.fiscalEnabled ?? true }, { label: "Serviços", enabled: settings?.servicesEnabled ?? true }]; }
function shortCheck(key: string) { return ({ legal: "Legal", tax: "Tributário", address: "Endereço", contact: "Contato", warehouse: "Estoque", users: "Equipe", catalog: "Catálogo", fiscal: "Fiscal", operation: "Horários" } as Record<string, string>)[key] || key; }
function dayLabel(day: number) { return ["Dom", "Seg", "Ter", "Qua", "Qui", "Sex", "Sáb"][day] || "Dia"; }
function taxLabel(value?: string) { return ({ simples_nacional: "Simples Nacional", lucro_presumido: "Lucro Presumido", lucro_real: "Lucro Real", mei: "MEI" } as Record<string, string>)[value || ""] || "Não informado"; }
function initials(value: string) { return value.split(/\s+/).filter(Boolean).slice(0, 2).map((item) => item[0]).join("").toUpperCase(); }
function formatDocument(value?: string | null) { const digits = String(value || "").replace(/\D/g, ""); return digits.length === 14 ? digits.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/, "$1.$2.$3/$4-$5") : value || "Não informado"; }
function formatActivity(value?: string | null) { const digits = String(value || "").replace(/\D/g, ""); return digits.length === 7 ? digits.replace(/^(\d{4})(\d)(\d{2})$/, "$1-$2/$3") : value || "Não informado"; }
function formatDate(value?: string | null) { return value ? date.format(new Date(value)) : "Não informada"; }
function dateInput(value?: string | null) { return value ? String(value).slice(0, 10) : ""; }
function address(item: Branch) { const line = [item.street, item.number, item.complement, item.district].filter(Boolean).join(", "), city = [item.city, item.state].filter(Boolean).join(" / "); return [line, city, item.zip].filter(Boolean).join(" · ") || "Não informado"; }
function relativeTime(value: string) { const seconds = Math.max(0, Math.round((Date.now() - new Date(value).valueOf()) / 1000)); if (seconds < 60) return "agora"; if (seconds < 3600) return `há ${Math.floor(seconds / 60)} min`; return `às ${dateTime.format(new Date(value))}`; }
